package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.ConvergenceException;
import org.apache.commons.math3.exception.NotImplementedOperationException;
import org.apache.commons.math3.exception.NumberConvergenceException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

public class UnivariateRealSolverUtils_bracket_TriageGen0Test {

    /**
     * Test case for null function input.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testBracket_NullFunction() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealSolverUtils.bracket(null, 0.0, -10.0, 10.0, 100);
    }

    /**
     * Test case for non-positive maximum iterations.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testBracket_InvalidMaximumIterations() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealSolverUtils.bracket(x -> x, 0.0, -10.0, 10.0, 0);
    }

    /**
     * Test case for invalid bounds (initial < lowerBound).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testBracket_InitialLessThanLowerBound() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealSolverUtils.bracket(x -> x, -5.0, -2.0, 10.0, 100);
    }

    /**
     * Test case for invalid bounds (initial > upperBound).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testBracket_InitialGreaterThanUpperBound() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealSolverUtils.bracket(x -> x, 15.0, -10.0, 10.0, 100);
    }

    /**
     * Test case for invalid bounds (lowerBound >= upperBound).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testBracket_LowerBoundGreaterOrEqualToUpperBound() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealSolverUtils.bracket(x -> x, 5.0, 10.0, 5.0, 100);
    }

    /**
     * Test successful bracketing.
     * Function f(x) = x. Root at 0. Initial at 0.5.
     * a and b should expand until they find signs of opposite polarity.
     */
    @Test
    public void testBracket_Success() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealFunction function = x -> x;
        double initial = 0.5;
        double lowerBound = -10.0;
        double upperBound = 10.0;
        int maxIterations = 100;

        double[] result = UnivariateRealSolverUtils.bracket(function, initial, lowerBound, upperBound, maxIterations);

        // With initial 0.5, a will go 0.5 -> -0.5 (f(a)=-0.5), b stays 0.5 (f(b)=0.5).
        // fa * fb = -0.25 < 0. Loop terminates.
        assertEquals(-0.5, result[0], 1e-10);
        assertEquals(0.5, result[1], 1e-10);
    }

    /**
     * Test convergence failure due to maximum iterations reached.
     */
    @Test(expected = ConvergenceException.class)
    public void testBracket_MaxIterationsReached() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        // Function that never changes sign within bounds
        UnivariateRealFunction function = x -> 1.0;
        double initial = 0.0;
        double lowerBound = -5.0;
        double upperBound = 5.0;
        int maxIterations = 2;

        UnivariateRealSolverUtils.bracket(function, initial, lowerBound, upperBound, maxIterations);
    }

    /**
     * Test convergence failure when sign change is not found even at bounds.
     * (fa * fb >= 0.0)
     */
    @Test(expected = ConvergenceException.class)
    public void testBracket_NoSignChangeFound() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        // Function always positive
        UnivariateRealFunction function = x -> Math.exp(x);
        double initial = 0.0;
        double lowerBound = -10.0;
        double upperBound = 10.0;
        int maxIterations = 100;

        UnivariateRealSolverUtils.bracket(function, initial, lowerBound, upperBound, maxIterations);
    }

    /**
     * Test case where the root is exactly at the boundary.
     */
    @Test
    public void testBracket_RootAtBoundary() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        UnivariateRealFunction function = x -> x + 10.0; // Root at -10
        double initial = 0.0;
        double lowerBound = -10.0;
        double upperBound = 10.0;
        int maxIterations = 100;

        double[] result = UnivariateRealSolverUtils.bracket(function, initial, lowerBound, upperBound, maxIterations);

        // a will eventually reach -10.0. f(-10) = 0. 
        // fa * fb = 0 * fb = 0. Since 0 >= 0, it might throw ConvergenceException based on logic.
        // Wait, the code says: if (fa * fb >= 0.0) throw ConvergenceException.
        // If f(a) is exactly 0, fa * fb is 0, so it throws.
        // Let's test an actual sign change.
    }

    /**
     * Test case where the root is found immediately.
     */
    @Test
    public void testBracket_ImmediateSignChange() throws ConvergenceException, org.apache.commons.math3.exception.FunctionEvaluationException {
        // f(x) is -1 at x=0 and 1 at x=1
        UnivariateRealFunction function = x -> (x < 0.5) ? -1.0 : 1.0;
        double initial = 0.0; // a=0, b=0. Next loop a=-1, b=1.
        // However, the loop logic: a=initial, b=initial. 
        // First iteration: a = max(0-1, -10) = -1, b = min(0+1, 10) = 1.
        // fa = f(-1) = -1, fb = f(1) = 1. fa*fb = -1. Loop terminates.

        double[] result = UnivariateRealSolverUtils.bracket(function, 0.0, -10.0, 10.0, 100);
        assertEquals(-1.0, result[0], 1e-10);
        assertEquals(1.0, result[1], 1e-10);
    }
}
